queries.cql:
// CrowdStrike CQL for Staged Accident Claim Correlation
// Identifies claims sharing professional enablers across unrelated accidents
claim_type="vehicle_accident"
| claim_date > now() - 365d
// Medical provider clustering
| groupBy(medical_provider, function=[
    count(field=accident_id, distinct=true, as=accident_count),
    count(field=claim_id, distinct=true, as=claim_count),
    collect([accident_id]),
    sum(claim_amount, as=total_claimed)
  ])
| accident_count >= 3
| provider_type := "medical"
| sort(accident_count, order=desc)
